/* ===================== REPORT CENTER ===================== */
VIEWS.reportcenter = function(mount, ctx){
  const {REPORT_LIST, REPORT_SOURCE} = window.GSM_REPORTS;
  const ay = ctx.state.ay || activeYearName();
  mount.innerHTML = pageHead("Report Center", REPORT_LIST.length+" report definitions available · more reports appear automatically as they are published from the backend") +
    `<div id="rcFilter"></div><div id="rcGrid" class="kpi-row" style="grid-template-columns:repeat(auto-fill,minmax(230px,1fr))"></div><div id="rcViewer"></div>`;

  const fb = FilterBar(byId("rcFilter"), [
    {key:'q',label:'Search Reports',type:'search',grow:true,placeholder:'Search by report name or number…'},
  ], (vals)=>renderGrid(vals.q||""));

  function renderGrid(q){
    q = (q||"").toLowerCase();
    const list = REPORT_LIST.filter(([id,name])=>!q||id.includes(q)||name.toLowerCase().includes(q));
    let html = "";
    list.forEach(([id,name])=>{
      html += `<div class="kpi" style="cursor:pointer" data-r="${id}"><div class="l" style="font-weight:700;color:var(--gold-2);background:none">RPT-${id}</div><div style="font-size:13px;font-weight:700;color:var(--navy);margin-top:4px;line-height:1.3">${esc(name)}</div><div class="d" style="color:var(--muted);font-weight:500;margin-top:6px">Open ›</div></div>`;
    });
    byId("rcGrid").innerHTML = html || `<div class="empty-state">No reports match your search.</div>`;
    qsa("[data-r]", byId("rcGrid")).forEach(el=>el.onclick=()=>openReport(el.dataset.r));
  }
  function openReport(id){
    const name = REPORT_LIST.find(r=>r[0]===id)[1];
    const src = REPORT_SOURCE[id] || {};
    let rows = [], columns = [];
    if(src.dataKey){
      rows = collection(src.dataKey);
      columns = src.columns;
    } else if(src.special==='students_master'){
      rows = REF.students.map(s=>({...s, __class: G.studentClass(ay,s.id)||''}));
      columns = [{key:'id',label:'SDMS Code'},{key:'name',label:'Full Name'},{key:'sex',label:'Sex'},{key:'__class',label:'Class'},{key:'status',label:'Status'}];
    } else if(src.special==='staff_directory'){
      rows = REF.staff; columns = [{key:'STAFF_ID',label:'Staff ID'},{key:'FULL_NAME',label:'Full Name'},{key:'ROLE_OR_POSITION',label:'Role'},{key:'PHONE',label:'Phone'},{key:'STATUS',label:'Status'}];
    } else if(src.special==='enrollment_by_class'){
      rows = classesForYear(ay).map(c=>({cls:c.CLASS_NAME, n: studentsInClass(ay,c.CLASS_ID).length, section:c.SECTION}));
      columns = [{key:'cls',label:'Class'},{key:'section',label:'Section'},{key:'n',label:'Enrolled Students'}];
    } else if(src.special==='data_quality'){
      const missing = REF.students.filter(s=>!s.sex||!s.status);
      rows = missing.map(s=>({id:s.id,name:s.name,issue:'Missing sex/status field'}));
      columns = [{key:'id',label:'SDMS Code'},{key:'name',label:'Name'},{key:'issue',label:'Data Issue'}];
    } else if(src.special==='attendance_summary'){
      rows = collection('attendance_sample'); columns=[{key:'STUDENT_ID',label:'Student'},{key:'DATE',label:'Date'},{key:'STATUS',label:'Status'}];
    } else if(src.special==='dod_kpi'){
      rows = [
        {area:'Discipline Cases Logged', n: collection('discipline_cases').length},
        {area:'Counselling Sessions', n: collection('counselling_sessions').length},
        {area:'Safety Incidents', n: collection('incident_register').length},
        {area:'Club Activities', n: collection('club_attendance').length},
      ];
      columns = [{key:'area',label:'KPI Area'},{key:'n',label:'Count This Period'}];
    } else {
      rows = []; columns = [{key:'note',label:'Note'}];
    }
    let html = `<div class="card"><div class="card-h"><h3>RPT-${id} — ${esc(name)}</h3><div class="page-actions"><button class="btn btn-outline btn-sm" id="rcClose">Close</button><button class="btn btn-primary btn-sm" id="rcPrintBtn">🖨️ Print</button></div></div><div class="card-b" id="rcResult"></div></div>`;
    byId("rcViewer").innerHTML = html;
    const dt = DataTable({ mount: byId("rcResult"), columns, rows, pageSize:10, emptyMsg:"No data currently logged for this report. It will populate automatically as records are entered." });
    byId("rcClose").onclick = ()=>{ byId("rcViewer").innerHTML=""; };
    byId("rcPrintBtn").onclick = ()=>{
      printReport({title:"RPT-"+id+" — "+name.toUpperCase(), subTitle:"Report Center", ay, term: ctx.state.term||activeTermName(ay), columns, rows: dt.getFiltered()});
    };
    byId("rcViewer").scrollIntoView({behavior:'smooth'});
  }
  renderGrid("");
};

