VIEWS.studentupload = function(mount, ctx){
  mount.innerHTML = pageHead("Student Upload & Enrolment","Upload a CSV (SDMS Code, Full Name, Sex, Class) — parsed and previewed locally") +
   `<div class="card"><div class="card-b">
      <input type="file" id="csvFile" accept=".csv">
      <div id="csvPreview" style="margin-top:14px"></div>
      <button class="btn btn-primary" id="csvCommit" style="margin-top:10px;display:none">Commit to Register</button>
    </div></div>`;
  let parsed = [];
  byId("csvFile").addEventListener("change", (e)=>{
    const f = e.target.files[0]; if(!f) return;
    const reader = new FileReader();
    reader.onload = ()=>{
      const lines = String(reader.result).split(/\r?\n/).filter(Boolean);
      const header = lines[0].split(",").map(h=>h.trim());
      parsed = lines.slice(1).map(l=>{ const c = l.split(","); const o={}; header.forEach((h,i)=>o[h]=c[i]?c[i].trim():""); return o; });
      let html = `<div style="font-size:12.5px;color:var(--muted);margin-bottom:6px">${parsed.length} rows parsed. Review before committing.</div>`;
      DataTable({ mount: (()=>{ const d=document.createElement('div'); byId("csvPreview").innerHTML=""; byId("csvPreview").appendChild(d); return d; })(), columns: header.map(h=>({key:h,label:h})), rows: parsed.slice(0,50), pageSize:10 });
      byId("csvPreview").insertAdjacentHTML("afterbegin", html);
      byId("csvCommit").style.display = "inline-flex";
    };
    reader.readAsText(f);
  });
  byId("csvCommit").onclick = ()=>{
    parsed.forEach(r=>{ addRecord('students', {id:r['SDMS Code']||r.STUDENT_ID||('NEW'+Date.now()+Math.random()), name:r['Full Name']||r.NAME, sex:r.Sex||r.SEX, status:'ACTIVE', year: ctx.state.ay}); });
    toast(parsed.length+" students committed to the register.");
  };
};
